class StockDashboard:
    """股票仪表板"""

    def __init__(self, symbol: str = "AAPL"):
        self.symbol = symbol.upper()
        self.port = PORT
        self.data = self._get_sample_data()

    def _get_sample_data(self) -> Dict:
        """获取示例数据"""
        return {
            "symbol": self.symbol,
            "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "price": 150.00,
            "change_pct": 1.25,
            "rsi": 65.5,
            "macd": 0.5,
            "sma20": 148.50,
            "sma50": 145.00,
            "trend_direction": "上涨",
            "trend_strength": 0.7,
            "support": 145.0,
            "resistance": 155.0,
            "signal": "HOLD",
            "target": 160.0,
            "stop_loss": 140.0,
            "confidence": 0.75,
            "pe": 25.5,
            "eps": 5.80,
            "dividend": 0.55,
            "revenue_growth": 8.5,
            "alerts": [
                {"level": "medium", "message": "RSI 超买: 65.5"},
                {"level": "low", "message": "价格变动 +1.25%"}
            ]
        }

    def _generate_html(self) -> str:
        """生成 HTML"""
        d = self.data

        # 颜色
        change_class = "positive" if d["change_pct"] >= 0 else "negative"
        signal_class = d["signal"].lower()

        # 警报 HTML
        alerts_html = ""
        for alert in d["alerts"]:
            alerts_html += f'<div class="alert {alert["level"]}">{alert["message"]}</div>'
        if not alerts_html:
            alerts_html = '<div style="color:#666">暂无警报</div>'

        return HTML_TEMPLATE.format(
            symbol=d["symbol"],
            timestamp=d["timestamp"],
            price=d["price"],
            change_class=change_class,
            change_pct=d["change_pct"],
            rsi=f'{d["rsi"]:.1f}',
            macd=f'{d["macd"]:.2f}',
            sma20=f'{d["sma20"]:.2f}',
            sma50=f'{d["sma50"]:.2f}',
            trend_direction=d["trend_direction"],
            trend_strength=d["trend_strength"],
            support=d["support"],
            resistance=d["resistance"],
            signal=d["signal"],
            signal_class=signal_class,
            target=d["target"],
            stop_loss=d["stop_loss"],
            confidence=d["confidence"],
            pe=d["pe"],
            eps=f'{d["eps"]:.2f}',
            dividend=f'{d["dividend"]:.2f}',
            revenue_growth=f'{d["revenue_growth"]:.1f}',
            alerts_html=alerts_html
        )

    def _serve(self):
        """启动 HTTP 服务器"""
        html = self._generate_html()

        class Handler(http.server.SimpleHTTPRequestHandler):
            def do_GET(self):
                if self.path == "/" or self.path == "/index.html":
                    self.send_response(200)
                    self.send_header("Content-type", "text/html; charset=utf-8")
                    self.end_headers()
                    self.wfile.write(html.encode("utf-8"))
                else:
                    self.send_response(404)
                    self.end_headers()

            def log_message(self, format, *args):
                pass  # 禁用日志

        with socketserver.TCPServer(("", self.port), Handler) as httpd:
            print(f"\n{'='*60}")
            print(f"🌐 Dashboard 启动: http://localhost:{self.port}")
            print(f"📊 股票: {self.symbol}")
            print(f"{'='*60}")
            httpd.serve_forever()

    def open(self, open_browser: bool = True):
        """打开仪表板"""
        # 在新线程中启动服务器
        server_thread = threading.Thread(target=self._serve, daemon=True)
        server_thread.start()

        if open_browser:
            import time
            time.sleep(1)  # 等待服务器启动
            webbrowser.open(f"http://localhost:{self.port}")

        print(f"\n按 Ctrl+C 停止服务器")


def main():
    import sys
    symbol = sys.argv[1] if len(sys.argv) > 1 else "AAPL"

    dashboard = StockDashboard(symbol)
    dashboard.open()


if __name__ == "__main__":
    main()

